#include <cassert>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
enum class Phase { Revealing, Ready, Choosing, Ended };
enum class Event { RevealFinished, AdvancePressed, ChoosePressed };
enum class Effect { None, ShowAll, NextLine, CommitChoice };
struct State { Phase phase; bool hasChoice; bool hasNext; };
Effect Handle(State& s, Event e) {
    if (s.phase == Phase::Ended) return Effect::None;
    if (s.phase == Phase::Revealing) {
        if (e == Event::RevealFinished || e == Event::AdvancePressed) {
            s.phase = Phase::Ready;
            return e == Event::AdvancePressed ? Effect::ShowAll : Effect::None;
        }
        return Effect::None;
    }
    if (s.phase == Phase::Ready && e == Event::AdvancePressed) {
        if (s.hasChoice) { s.phase = Phase::Choosing; return Effect::None; }
        if (s.hasNext) { s.phase = Phase::Revealing; return Effect::NextLine; }
        s.phase = Phase::Ended; return Effect::None;
    }
    if (s.phase == Phase::Choosing && e == Event::ChoosePressed) {
        s.phase = Phase::Ended; return Effect::CommitChoice;
    }
    return Effect::None;
}
int main() {
    State a{Phase::Revealing,false,true};
    assert(Handle(a,Event::AdvancePressed)==Effect::ShowAll);
    assert(a.phase==Phase::Ready);
    assert(Handle(a,Event::AdvancePressed)==Effect::NextLine);
    assert(a.phase==Phase::Revealing);
    State b{Phase::Revealing,true,true};
    assert(Handle(b,Event::RevealFinished)==Effect::None);
    assert(b.phase==Phase::Ready);
    assert(Handle(b,Event::AdvancePressed)==Effect::None);
    assert(b.phase==Phase::Choosing);
    assert(Handle(b,Event::AdvancePressed)==Effect::None);
    assert(Handle(b,Event::ChoosePressed)==Effect::CommitChoice);
    assert(Handle(b,Event::ChoosePressed)==Effect::None);
    State c{Phase::Ready,false,false};
    assert(Handle(c,Event::AdvancePressed)==Effect::None);
    assert(c.phase==Phase::Ended);
    const Event events[]={Event::RevealFinished,Event::AdvancePressed,Event::ChoosePressed};
    // Exhaustively inspect every six-event sequence for each flag pair.
    for (int flags=0;flags<4;++flags)
      for (int sequence=0;sequence<729;++sequence) {
        State s{Phase::Revealing,(flags&1)!=0,(flags&2)!=0};
        int value=sequence, commits=0;
        for (int step=0;step<6;++step) {
            const Event e=events[value%3];value/=3;
            const Phase before=s.phase;const Effect effect=Handle(s,e);
            if (before==Phase::Revealing) assert(effect!=Effect::NextLine);
            if (before==Phase::Ended) assert(s.phase==Phase::Ended && effect==Effect::None);
            if (effect==Effect::CommitChoice) ++commits;
            assert(commits<=1);
        }
      }
}
